#
# Turns the Tenstorrent firmware image into C++ source for the client.
# usage: bin2c.sh IMAGE.bin SYMBOL COMPILER-VERSION > OUTPUT.cpp

image=$1
symbol=$2
compiler=$3

cat <<EOF
/*
 * Generated by 'make tt-firmware' from r72tt_tile.c (see r72tt_tile.c and
 * docs/readme.tenstorrent). Do not edit.
 * Compiler: $compiler
 */

extern "C" const unsigned char ${symbol}[] = {
EOF
od -An -v -t x1 "$image" | sed -e 's/[0-9a-f][0-9a-f]/0x&,/g' -e 's/^ */  /' -e 's/ *$//'
cat <<EOF
};
extern "C" const unsigned int ${symbol}_size = sizeof(${symbol});
EOF
